 "content": "def transform(grid):
    # The 3x3 objects are separated by blank space. Return the unique object
    # containing three distinct non-background colors.
    h, w = len(grid), len(grid[0])
    seen = set()
    objs = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx)); stack.append((ny,nx))
            objs.append(cells)
    candidates = []
    for cells in objs:
        colors = {grid[y][x] for y,x in cells}
        if len(colors) == 3:
            minr = min(y for y,x in cells); maxr = max(y for y,x in cells)
            minc = min(x for y,x in cells); maxc = max(x for y,x in cells)
            candidates.append([row[minc:maxc+1] for row in grid[minr:maxr+1]])
    return candidates[0]
